def copiar_fks_a_m2m(apps, schema_editor):
    """Copia los FKs legacy (desagregacion_geografica/tematica) al nuevo M2M.

    Usa bulk_create sobre la tabla through: una sola inserción masiva en vez
    de SELECT+DELETE+INSERT por serie (lo que hace .set()).
    """
    GraficoSerie = apps.get_model('indicadores', 'GraficoSerie')
    Through = GraficoSerie.desagregaciones.through

    total = GraficoSerie.objects.count()
    print(f"\n  [0094] Copiando FKs legacy al M2M en {total} series...")

    rows = []
    qs = GraficoSerie.objects.values_list(
        'id', 'desagregacion_geografica_id', 'desagregacion_tematica_id'
    ).iterator(chunk_size=2000)
    for i, (sid, geo_id, tem_id) in enumerate(qs, 1):
        if geo_id:
            rows.append(Through(graficoserie_id=sid, desagregacion_id=geo_id))
        if tem_id:
            rows.append(Through(graficoserie_id=sid, desagregacion_id=tem_id))
        if i % 1000 == 0:
            print(f"  [0094]   {i}/{total} series leídas...")

    print(f"  [0094] Insertando {len(rows)} relaciones en la tabla M2M...")
    Through.objects.bulk_create(rows, batch_size=2000, ignore_conflicts=True)
    print(f"  [0094] Listo: {len(rows)} relaciones copiadas.")


def revertir_m2m_a_fks(apps, schema_editor):
    """Reversa: restaura los FKs desde el M2M (primera geo y primera temática)."""
    GraficoSerie = apps.get_model('indicadores', 'GraficoSerie')
    total = GraficoSerie.objects.count()
    print(f"\n  [0094] Revirtiendo M2M a FKs en {total} series...")
    for i, serie in enumerate(GraficoSerie.objects.prefetch_related('desagregaciones__dominio').iterator(chunk_size=2000), 1):
        geo_id = tem_id = None
        for d in serie.desagregaciones.all():
            if d.dominio and d.dominio.tipo == 'geografica' and geo_id is None:
                geo_id = d.id
            elif d.dominio and d.dominio.tipo == 'tematica' and tem_id is None:
                tem_id = d.id
        serie.desagregacion_geografica_id = geo_id
        serie.desagregacion_tematica_id = tem_id
        serie.save(update_fields=['desagregacion_geografica', 'desagregacion_tematica'])
        if i % 1000 == 0:
            print(f"  [0094]   {i}/{total} series revertidas...")


